async (page) => {
  const insp = async () => page.evaluate(async () => {
    const out = [];
    for (const a of document.querySelectorAll('a[download]')) {
      const r = await fetch(a.href);
      const b = await r.blob();
      const buf = new Uint8Array(await b.arrayBuffer());
      out.push({ download: a.download, type: b.type, size: b.size, magic: [...buf.slice(0,12)].map(x=>x.toString(16).padStart(2,'0')).join(' ') });
    }
    return out;
  });
  const moz = await insp();
  // switch right side to WebP
  const sels = await page.$$('select');
  // pick the one whose value is a codec
  const info = await page.evaluate(() => [...document.querySelectorAll('select')].map(s=>({v:s.value, opts:[...s.options].map(o=>o.value)})));
  return JSON.stringify({ moz, info }, null, 1);
}

