async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  await page.getByRole('button', { name: /Large photo/ }).click();
  await page.waitForTimeout(2500);
  const inspect = async () => page.evaluate(async () => {
    const out = [];
    for (const a of document.querySelectorAll('a[download]')) {
      const r = await fetch(a.href); const b = await r.blob();
      const buf = new Uint8Array(await b.arrayBuffer());
      let dims = null;
      try { const bmp = await createImageBitmap(b); dims = [bmp.width, bmp.height]; } catch(e) { dims = 'decode-fail'; }
      out.push({ download: a.download, type: b.type, size: b.size, magic: [...buf.slice(0,8)].map(x=>x.toString(16).padStart(2,'0')).join(' '), dims });
    }
    return out;
  });
  const identity = await inspect();
  await page.getByLabel('Compress codec').selectOption('webp');
  await page.waitForTimeout(2500);
  const webp = await inspect();
  await page.getByLabel('Compress codec').selectOption('mozjpeg');
  await page.waitForTimeout(2500);
  const jpeg = await inspect();
  return { log, identity, webp, jpeg };
}

