      />
      <path
        className="back-x"
        d="M-0.42 -0.42L0.42 0.42M0.42 -0.42L-0.42 0.42"
        stroke="#fff"
        strokeWidth="0.19"
        strokeLinecap="round"
        fill="none"
      />
    </svg>
  );
