@import "tailwindcss";

/* ---------------------------------------------------------------
   Design tokens
   --------------------------------------------------------------- */
:root {
  --pink: #ff3385;
  --hot-pink: #f06;
  --white: #fff;
  --black: #000;
  --off-black: #1d1d1d;
  --blue: #5fb4e4;
  --dim-blue: #0a7bcc;
  --deep-blue: #09f;
  --light-blue: #76c8ff;
  --less-light-gray: #bcbcbc;
  --medium-light-gray: #d1d1d1;
  --light-gray: #eaeaea;
  --dark-gray: #333;
  --dim-text: #343a3e;
  --dark-text: #142630;

  --ui-font: "HelveticaNeue-Light", "Helvetica Neue Light", "Helvetica Neue",
    Helvetica, Arial, "Lucida Grande", sans-serif;
  --mono-font: ui-monospace, "SFMono-Regular", "DejaVu Sans Mono", Menlo,
    Consolas, monospace;

  --options-radius: 7px;
  --checker: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 2 2'%3E%3Cpath d='M1 2V0h1v1H0v1z' fill-opacity='.05'/%3E%3C/svg%3E");
}

/* ---------------------------------------------------------------
   Base
   --------------------------------------------------------------- */
html {
  font-size: 12px;
}

html,
body {
  padding: 0;
  margin: 0;
  font: 12px/1.3 var(--ui-font);
  overscroll-behavior: none;
  background: var(--checker);
  background-size: 20px 20px;
}

html,
body,
#app {
  height: 100%;
  overflow: hidden;
}

#app {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
}

a,
button,
img,
input,
select,
textarea {
  -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
}

a,
button,
img,
[inert] {
  user-select: none;
  -webkit-user-select: none;
  -webkit-user-drag: none;
  -webkit-touch-callout: none;
}

.abs-fill {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
}

.plain-btn {
  cursor: pointer;
  background: none;
  border: none;
  font: inherit;
  padding: 0;
  margin: 0;
  color: inherit;
}
.plain-btn:focus {
  outline: none;
}

/* ===============================================================
   INTRO PAGE
   =============================================================== */
.intro-view {
  -webkit-overflow-scrolling: touch;
  overflow-y: auto;
  overscroll-behavior: contain;
  display: grid;
  grid-template-rows: 1fr max-content max-content;
  font-size: 1.2rem;
  color: var(--dim-text);
}

.intro-hero {
  min-height: 541px;
  display: grid;
  grid-template-rows: max-content max-content;
  justify-items: center;
  position: relative;
  --blob-pink: var(--hot-pink);
  --center-blob-opacity: 0.3;
}
@media (min-width: 600px) {
  .intro-hero {
    min-height: 688px;
  }
}

.logo-row {
  margin: 5rem 0 1rem;
}
.logo-mark {
  transform: translate(-1%);
  width: 189px;
  height: auto;
  display: block;
}

/* --- the big pink drop target --- */
.drop-zone {
  position: relative;
  color: var(--white);
  font-style: italic;
  font-size: 1.2rem;
  width: max-content;
  max-width: 100vw;
  display: grid;
  justify-items: center;
}

.drop-blob {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  fill: var(--blob-pink);
}
.drop-blob path {
  opacity: var(--center-blob-opacity);
  transform-origin: center;
  animation: blob-drift 14s ease-in-out infinite;
}
.drop-blob path:nth-child(2) {
  animation-duration: 18s;
  animation-direction: reverse;
}
.drop-blob path:nth-child(3) {
  animation-duration: 22s;
}
.drop-blob path:nth-child(4) {
  animation-duration: 17s;
  animation-direction: reverse;
}

/* Slow, low-amplitude drift that reads like the reference's living blob. */
@keyframes blob-drift {
  0%,
  100% {
    transform: rotate(0deg) scale(1);
  }
  50% {
    transform: rotate(6deg) scale(1.04);
  }
}

@media (prefers-reduced-motion: reduce) {
  .drop-blob path {
    animation: none;
  }
}

.drop-inner {
  position: relative;
  --size: 29rem;
  max-width: var(--size);
  width: 100vw;
  height: var(--size);
  display: grid;
  grid-template-rows: max-content max-content;
  justify-items: center;
  align-content: center;
  gap: 0.7rem;
}
@media (min-width: 600px) {
  .drop-inner {
    --size: 36rem;
  }
}

.drop-icon-btn {
  --size: 5rem;
  width: var(--size);
  height: var(--size);
  fill: var(--white);
  transform: translate(4.3%, -1%);
}
.drop-icon-btn svg {
  width: 100%;
  height: 100%;
  display: block;
}

.paste-link {
  text-decoration: underline;
  font: inherit;
  color: inherit;
}

.drop-hint {
  font-style: italic;
}
@media (max-width: 599px) {
  .drop-hint .drop-word {
    display: none;
  }
}

/* --- blue demos band --- */
.demos-band {
  position: relative;
  background: var(--deep-blue);
  padding-bottom: 5.2vw;
}
@media (max-width: 599px) {
  .demos-band {
    padding-bottom: 12vw;
  }
}

.band-wave {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 100%;
  width: 100%;
  display: block;
  height: auto;
  aspect-ratio: 1920 / 140;
}
.band-wave .wave-main {
  fill: var(--deep-blue);
}
.band-wave .wave-sub {
  fill: var(--light-blue);
}

.demos-pad {
  padding: 2em 0;
}

.demos-heading {
  color: var(--white);
  margin: 0;
  font-size: 2rem;
  text-align: center;
  font-weight: 400;
}
.demos-heading strong {
  font-weight: 700;
}

.demo-list {
  display: grid;
  gap: 3rem;
  justify-items: center;
  justify-content: center;
  padding: 0;
  margin: 3rem auto;
  --demo-size: 80px;
  grid-template-columns: repeat(auto-fit, var(--demo-size));
  list-style: none;
}
@media (min-width: 740px) {
  .demo-list {
    --demo-size: 100px;
    gap: 6rem;
  }
}
.demo-list > li {
  display: block;
}

.demo-card {
  transition: scale 0.4s ease-in-out;
}
.demo-card:hover {
  scale: 1.05;
}

.demo-avatar {
  border-radius: var(--demo-size);
  position: relative;
  overflow: hidden;
  width: var(--demo-size);
  height: var(--demo-size);
}
.demo-avatar img {
  width: var(--demo-size);
  height: var(--demo-size);
  display: block;
}

.demo-badge {
  background: var(--dim-blue);
  border-radius: 1000px;
  color: var(--white);
  width: max-content;
  padding: 0.5rem 1.2rem;
  margin: 0.7rem auto 0;
}

/* --- transition wave under the blue band --- */
.band-tail {
  position: relative;
  height: 0;
}
.band-tail svg {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: auto;
  display: block;
  aspect-ratio: 1920 / 79;
}
.band-tail .wave-info {
  fill: var(--white);
}

/* --- feature sections --- */
.info-block {
  position: relative;
  background: var(--white);
  padding: 5em 2em;
}
@media (min-width: 1200px) {
  .info-block {
    padding: 5em 0;
  }
}

.info-inner {
  max-width: 1000px;
  margin: 0 auto;
}

.info-grid {
  display: grid;
  align-items: center;
  grid-template-columns: 1fr;
  gap: 1em;
  grid-template-areas: "text" "img";
}
@media (min-width: 712px) {
  .info-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-areas: "text img";
  }
  .info-block:nth-of-type(2n) .info-grid {
    grid-template-areas: "img text";
  }
}

.info-copy {
  display: flex;
  flex-flow: column wrap;
  max-width: 27em;
  justify-self: center;
  grid-area: text;
}
@media (min-width: 712px) {
  .info-copy {
    justify-self: start;
  }
  .info-block:nth-of-type(2n) .info-copy {
    text-align: right;
    justify-self: end;
  }
}

.info-heading {
  color: var(--pink);
  font-size: 3em;
  margin: 0;
  font-weight: 400;
}

.info-body {
  font-size: 1.5em;
  line-height: 1.75;
  margin: 1em 0 0.5em;
}

.info-figure {
  grid-area: img;
  margin: 0;
}
.info-figure img {
  display: block;
  width: 100%;
  height: auto;
  max-width: 400px;
  margin: 0 auto;
}
@media (min-width: 768px) {
  .info-figure img {
    margin: 0 0 0 auto;
  }
  .info-block:nth-of-type(2n) .info-figure img {
    margin: 0;
  }
}

/* --- footer --- */
.site-footer {
  background: var(--white);
  padding-top: 5em;
}

.footer-band {
  position: relative;
  background: var(--light-gray);
}
.footer-band > svg {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 100%;
  width: 100%;
  height: auto;
  display: block;
  aspect-ratio: 1920 / 79;
}
.footer-band .wave-footer {
  fill: var(--light-gray);
}

.footer-pad {
  padding: 2em;
}

.footer-links {
  display: grid;
  grid-auto-rows: max-content;
  justify-items: center;
  gap: 2rem;
}
@media (min-width: 480px) {
  .footer-links {
    justify-content: end;
    grid-auto-flow: column;
    align-items: center;
    gap: 4rem;
  }
}

.footer-link {
  text-decoration: none;
  color: inherit;
}
.footer-link:hover {
  color: var(--dim-blue);
}
.footer-link.with-mark {
  display: grid;
  grid-template-columns: 1.8em max-content;
  align-items: center;
  gap: 0.6em;
}
.footer-link.with-mark img {
  width: 100%;
  height: auto;
}

/* --- install button --- */
.install-btn {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: var(--deep-blue);
  border-radius: 0.4em;
  color: var(--white);
  padding: 0.5em 1em;
  font-size: 1.6rem;
  cursor: pointer;
  border: none;
  animation: fade-in 0.6s ease-in-out;
  z-index: 5;
}
.install-btn:hover {
  background: #0a8ae6;
}

@keyframes fade-in {
  0% {
    opacity: 0;
  }
}

/* ===============================================================
   SNACKBAR
   =============================================================== */
.snackbar {
  position: fixed;
  display: flex;
  box-sizing: border-box;
  left: 50%;
  bottom: 24px;
  width: 344px;
  margin-left: -172px;
  background: #2a2a2a;
  border-radius: 2px;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
  transform-origin: center;
  color: #eee;
  z-index: 100;
  animation: snack-show 0.3s ease 1 forwards;
}
.snackbar.hiding {
  animation: snack-hide 0.3s ease 1 forwards;
}
.snackbar-text {
  flex: 1 1 auto;
  padding: 16px;
  font-size: 100%;
}
.snackbar-action {
  position: relative;
  flex: 0 1 auto;
  padding: 8px;
  height: 100%;
  margin: auto 8px auto -8px;
  min-width: 5em;
  background: none;
  border: none;
  border-radius: 3px;
  color: #90ee90;
  font-weight: inherit;
  letter-spacing: 0.05em;
  font-size: 100%;
  text-transform: uppercase;
  text-align: center;
  cursor: pointer;
  transition: background-color 0.2s ease;
}
.snackbar-action:hover {
  background-color: rgba(0, 0, 0, 0.15);
}
@media (max-width: 400px) {
  .snackbar {
    width: 100%;
    bottom: 0;
    left: 0;
    margin-left: 0;
    border-radius: 0;
  }
}
@keyframes snack-show {
  0% {
    opacity: 0;
    transform: scale(0.5);
  }
}
@keyframes snack-hide {
  to {
    opacity: 0;
    transform: translateY(100%);
  }
}

/* ===============================================================
   EDITOR
   =============================================================== */
.editor-root {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.editor-stage {
  touch-action: none;
}
.editor-stage::after {
  content: "";
  position: absolute;
  display: block;
  inset: 10px;
  background-color: rgba(0, 0, 0, 0.1);
  border: 2px dashed var(--pink);
  border-radius: 10px;
  opacity: 0;
  transform: scale(0.95);
  transition: transform 0.2s ease-in, opacity 0.2s ease-in;
  pointer-events: none;
  z-index: 20;
}
.editor-stage.drag-valid::after {
  opacity: 1;
  transform: scale(1);
  transition-timing-function: ease-out;
}

.editor-shell {
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-rows: max-content 1fr;
  grid-template-areas: "header" "opts";
}
@media (min-width: 600px) {
  .editor-shell {
    grid-template:
      "header header header" max-content
      "optsLeft viewportOpts optsRight" 1fr
      / max-content 1fr max-content;
  }
}
/*
 * Narrow screens lay the controls over the image: a full-height options
 * column down the right, the original-image panel pinned bottom-left.
 */


/* --- back button --- */
.back-btn {
  position: relative;
  grid-area: header;
  margin: 9px;
  place-self: start;
  width: 58px;
  height: 55px;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  z-index: 6;
}
.back-btn svg {
  width: 47px;
  overflow: visible;
  display: block;
}
@media (min-width: 600px) {
  .back-btn {
    margin: 14px;
  }
  .back-btn svg {
    width: 58px;
  }
}
.back-blob {
  fill: var(--hot-pink);
  opacity: 0.77;
}
.back-x {
  fill: var(--white);
}

/* --- viewer --- */
.viewer {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: transparent;
}
/*
 * Backdrop behind the bitmap. Squoosh defaults to the transparent checker
 * (opaque images hide it entirely); toggling the background dims the stage
 * so alpha channels read clearly.
 */
.viewer-overlay {
  position: absolute;
  inset: 0;
  background: #000;
  opacity: 0;
  transition: opacity 0.5s;
  z-index: 0;
}
.viewer-overlay.alt {
  opacity: 0.8;
}
.viewer-canvas {
  position: relative;
  display: block;
  transform-origin: center center;
  z-index: 1;
  will-change: transform;
}
.viewer-canvas img {
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.viewer-canvas.smooth img {
  image-rendering: auto;
}
.viewer-canvas.crisp img {
  image-rendering: pixelated;
}

/* --- two-up --- */
.two-up {
  --split-point: 50%;
  --bar-size: 4px;
  --bar-touch-size: 30px;
  --track-color: var(--pink);
  position: absolute;
  inset: 0;
}
/* Both layers stack; each is clipped at the divider. */
.two-up > img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.two-up > img.clip-left {
  clip-path: inset(0 calc(100% - var(--split-point)) 0 0);
}
.two-up > img.clip-right {
  clip-path: inset(0 0 0 var(--split-point));
}
.two-up-handle {
  touch-action: none;
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: var(--bar-touch-size);
  transform: translateX(var(--split-point)) translateX(-50%);
  will-change: transform;
  cursor: ew-resize;
  z-index: 3;
}
.two-up-handle::before {
  content: "";
  display: block;
  height: 100%;
  width: var(--bar-size);
  margin: 0 auto;
  background: var(--track-color);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
}
.two-up-knob {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 40px;
  height: 40px;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* --- viewport controls --- */
.viewer-controls {
  display: flex;
  justify-content: center;
  overflow: hidden;
