/* --- options panels --- */
.opts-panel {
  position: relative;
  color: #fff;
  font-size: 1.2rem;
  max-width: 400px;
  margin: 0 auto;
  width: calc(100% - 60px);
  max-height: 100%;
  grid-area: opts;
  display: grid;
  grid-template-rows: 1fr max-content;
  align-content: end;
  align-self: end;
  z-index: 5;
}
@media (min-width: 600px) {
