  grid-template-columns: 1fr;
  grid-auto-columns: max-content;
  grid-auto-flow: column;
  gap: 0.8rem;
  align-items: center;
}
.panel-title .title-actions {
  display: grid;
  grid-auto-columns: max-content;
  grid-auto-flow: column;
  gap: 0.8rem;
  align-items: center;
}
/* Original-image panel uses a black header instead of the pink/blue theme. */
.panel-title.is-original-title {
  background-color: var(--black);
  color: var(--white);
}
.title-btn {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  color: inherit;
  display: block;
}
.title-btn svg {
  --size: 20px;
  display: block;
  width: var(--size);
  height: var(--size);
}
.title-btn:focus {
