/* --- select --- */
.sel-wrap {
  position: relative;
}
.sel-wrap select {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  box-sizing: border-box;
  padding: 10px 35px 10px 10px;
  background: var(--dark-gray);
  color: #fff;
  font: inherit;
  font-size: 1.2rem;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}
.sel-wrap .sel-arrow {
  position: absolute;
  right: 13px;
  top: 50%;
  transform: translateY(-50%);
  fill: #fff;
  width: 10px;
  pointer-events: none;
}

/* --- toggle switch --- */
.switch {
  display: inline-block;
  position: relative;
}
/* The real input stretches over the visual track and takes the clicks. */
.switch input {
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0;
  margin: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
}
.switch .track {
  --thumb-size: 14px;
  background: var(--black);
  border-radius: 1000px;
  width: 24px;
  padding: 3px calc(var(--thumb-size) / 2 + 3px);
  display: block;
  box-sizing: content-box;
  /* Visual only — the wrapping label / real input receives the clicks. */
  pointer-events: none;
}
.switch input:focus-visible + .track {
  outline: #fff solid 2px;
}
.switch .thumb-track {
  transition: transform 0.2s;
  display: block;
}
.switch .thumb {
  position: relative;
  width: var(--thumb-size);
  height: var(--thumb-size);
  background: var(--less-light-gray);
  border-radius: 100%;
  transform: translateX(calc(var(--thumb-size) / -2));
  overflow: hidden;
  display: block;
}
.switch .thumb::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--main-theme-color);
  opacity: 0;
  transition: opacity 0.2s;
}
.switch input:checked + .track .thumb-track {
  transform: translateX(100%);
}
.switch input:checked + .track .thumb::before {
  opacity: 1;
}

/* --- expander (advanced settings) --- */
