async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  await page.getByRole('button', { name: /Large photo/ }).click();
  await page.waitForTimeout(2800);
  await page.screenshot({ path: '.playwright-mcp/r3-editor.png' });
  const before = await page.evaluate(() => getComputedStyle(document.querySelector('.two-up')).getPropertyValue('--split-point'));
  const knob = page.locator('.two-up-handle');
  const box = await knob.boundingBox();
  await page.mouse.move(box.x + box.width/2, box.y + box.height/2);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width/2 + 300, box.y + box.height/2, { steps: 10 });
  await page.mouse.up();
  await page.waitForTimeout(400);
  const after = await page.evaluate(() => getComputedStyle(document.querySelector('.two-up')).getPropertyValue('--split-point'));
  await page.screenshot({ path: '.playwright-mcp/r3-split.png' });
  return { log, before, after };
}

