  await page.goto('http://localhost:8108/index.html');
  await page.waitForTimeout(400);
  // upload the distinctive PNG
  await page.locator('input[type=file]').first().setInputFiles('/tmp/upload-test.png');
  await page.waitForTimeout(2500);
  const res = await page.evaluate(async () => {
    const a = document.querySelector('a[download]');
    const b = await (await fetch(a.href)).blob();
    const buf = new Uint8Array(await b.arrayBuffer());
    let h=0; for (let i=0;i<buf.length;i++) h=(h*31+buf[i])>>>0;
    return { name: a.download, size: buf.length, hash: h };
  });
  return res;
}

