async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  const snap = () => page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')].pop();
    const b = await (await fetch(a.href)).blob();
    const buf = new Uint8Array(await b.arrayBuffer());
    let dims=null, ok=true;
    try { const bm = await createImageBitmap(b); dims=[bm.width,bm.height]; } catch(e){ ok=false; }
    return { name: a.download, type: b.type, magic: [...buf.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' '), dims, ok };
  });
  await page.getByRole('button', { name: /Large photo/ }).click();
  await page.waitForTimeout(3200);
  const base = await snap();
  const sel = page.locator('select[aria-label="Compress codec"]').nth(1);
  await sel.selectOption('webp'); await page.waitForTimeout(2400);
  const webp = await snap();
  await sel.selectOption('avif'); await page.waitForTimeout(2400);
  const avif = await snap();
  await sel.selectOption('qoi'); await page.waitForTimeout(2400);
  const qoi = await snap();
  return { log, base, webp, avif, qoi };
}

